import React, { useState, useEffect } from 'react';
import { marketAPI } from '../api';
import '../styles/Backtest.css';

const Backtest = () => {
  const [figi, setFigi] = useState('');
  const [currentPrice, setCurrentPrice] = useState(null);
  const [prices, setPrices] = useState([]);
  const [predictions, setPredictions] = useState([]);
  const [backtestResult, setBacktestResult] = useState(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');

  // Получение текущей цены по FIGI
  const fetchCurrentPrice = async () => {
    if (!figi.trim()) {
      setError('Введите FIGI');
      return;
    }

    setLoading(true);
    setError('');
    try {
      const response = await marketAPI.getCurrentPrice(figi.trim());
      if (response.data.status === 'ok') {
        setCurrentPrice(response.data.current_price);
        setError('');
      } else {
        setError('Не удалось получить цену');
      }
    } catch (err) {
      setError('Ошибка при получении цены: ' + (err.response?.data?.detail || err.message));
      setCurrentPrice(null);
    } finally {
      setLoading(false);
    }
  };

  // Добавление текущей цены в список
  const addPrice = () => {
    if (currentPrice !== null && !isNaN(currentPrice)) {
      const newPrice = parseFloat(currentPrice);
      setPrices(prev => [...prev, newPrice]);
      
      // Генерация случайного предсказания (±5% от текущей цены)
      const randomChange = (Math.random() - 0.5) * 0.1; // ±5%
      const prediction = newPrice * (1 + randomChange);
      setPredictions(prev => [...prev, parseFloat(prediction.toFixed(2))]);
      
      setError('');
    } else {
      setError('Сначала получите текущую цену');
    }
  };

  // Запуск бэктеста
  const runBacktest = async () => {
    if (prices.length === 0) {
      setError('Добавьте хотя бы одну цену');
      return;
    }

    setLoading(true);
    try {
      const response = await backtestAPI.runBacktest(prices, predictions);
      setBacktestResult(response.data);
    } catch (err) {
      setError('Ошибка при запуске бэктеста: ' + (err.response?.data?.detail || err.message));
    } finally {
      setLoading(false);
    }
  };

  // Очистка всех данных
  const clearData = () => {
    setPrices([]);
    setPredictions([]);
    setBacktestResult(null);
    setCurrentPrice(null);
    setError('');
  };

  return (
    <div className="backtest-container">
      <h2>Бэктестирование торговой стратегии</h2>
      
      <div className="input-section">
        <div className="input-group">
          <label htmlFor="figi-input">FIGI инструмента:</label>
          <input
            id="figi-input"
            type="text"
            value={figi}
            onChange={(e) => setFigi(e.target.value)}
            placeholder="Введите FIGI (например, BBG000000000)"
            className="figi-input"
          />
          <button 
            onClick={fetchCurrentPrice} 
            disabled={loading || !figi.trim()}
            className="btn-primary"
          >
            {loading ? 'Загрузка...' : 'Получить цену'}
          </button>
        </div>

        {currentPrice !== null && (
          <div className="current-price">
            <h3>Текущая цена: {currentPrice} ₽</h3>
            <button 
              onClick={addPrice}
              className="btn-secondary"
            >
              Добавить цену в список
            </button>
          </div>
        )}
      </div>

      {error && <div className="error-message">{error}</div>}

      {/* Списки цен и предсказаний */}
      {(prices.length > 0 || predictions.length > 0) && (
        <div className="data-lists">
          <div className="list-container">
            <h4>Исторические цены:</h4>
            <div className="price-list">
              {prices.map((price, index) => (
                <div key={index} className="price-item">
                  #{index + 1}: {price} ₽
                </div>
              ))}
            </div>
          </div>

          <div className="list-container">
            <h4>Предсказания:</h4>
            <div className="prediction-list">
              {predictions.map((prediction, index) => (
                <div key={index} className="prediction-item">
                  #{index + 1}: {prediction} ₽
                </div>
              ))}
            </div>
          </div>
        </div>
      )}

      {/* Кнопки управления */}
      <div className="control-buttons">
        <button 
          onClick={runBacktest} 
          disabled={loading || prices.length === 0}
          className="btn-success"
        >
          Запустить бэктест
        </button>
        
        <button 
          onClick={clearData}
          className="btn-danger"
        >
          Очистить все
        </button>
      </div>

      {/* Результаты бэктеста */}
      {backtestResult && (
        <div className="backtest-results">
          <h3>Результаты бэктеста</h3>
          <div className="results-grid">
            <div className="result-item">
              <span>Общая доходность:</span>
              <span className={backtestResult.total_return >= 0 ? 'positive' : 'negative'}>
                {(backtestResult.total_return * 100).toFixed(2)}%
              </span>
            </div>
            <div className="result-item">
              <span>Количество сделок:</span>
              <span>{backtestResult.total_trades}</span>
            </div>
            <div className="result-item">
              <span>Успешных сделок:</span>
              <span>{backtestResult.successful_trades}</span>
            </div>
            <div className="result-item">
              <span>Процент успеха:</span>
              <span>{(backtestResult.success_rate * 100).toFixed(1)}%</span>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default Backtest;
